function localDayKey(date: Date){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;}
function shiftDayKey(day: string, offset: number){const date=new Date(`${day}T12:00:00`);date.setDate(date.getDate()+offset);return localDayKey(date);}
const seedDay=localDayKey(new Date());
const seededPatients: Patient[] = [...starter, ...extraNames.map((name,i)=>{const index=i+10, wing=index<19?'A':index<38?'B':index<56?'C':'D', bedNum=index<19?index+1:index<38?index-18:index<56?index-37:index-55; const temp=i<28?Number((36.4+(i%19)*.12).toFixed(1)):undefined; return {id:index+1,name:`${name} ${['Sharma','Patil','Reddy','Khan','Desai','Pillai','Joshi','Mishra'][i%8]}`,age:18+(i*7)%63,sex:i%3===0?'F':'M',bed:`${wing}-${String(bedNum).padStart(2,'0')}`,temp,tempAt:temp===undefined?undefined:`${String(7+Math.floor(i/5)).padStart(2,'0')}:${String((i*11)%60).padStart(2,'0')}`,visited:i<10,streak:i%6===0?3:i%4,ready:i%6===0&&temp!==undefined};})];
