  useEffect(()=>{const keys=(event:KeyboardEvent)=>{const target=event.target;const editing=target instanceof HTMLElement&&(target.isContentEditable||target.matches('input,textarea,select'));if(editing||document.querySelector('[role="dialog"]'))return;if(event.key==='/'){event.preventDefault();document.querySelector<HTMLInputElement>('.searchbox input')?.focus()}if(event.key==='?'&&event.shiftKey)setTab('Help');if(event.altKey&&event.key==='1')switchRole('Nurse');if(event.altKey&&event.key==='2')switchRole('Doctor');if(event.altKey&&event.key==='3')switchRole('Front Desk');if(event.altKey&&event.key==='4')switchRole('Centre Lead')};window.addEventListener('keydown',keys);return()=>window.removeEventListener('keydown',keys)},[]);
  useEffect(()=>{const dismiss=(event:PointerEvent)=>{const target=event.target;if(target instanceof Element&&!target.closest('.role-control'))setRoleMenuOpen(false);if(target instanceof Element&&!target.closest('.filter-control'))setFilterMenuOpen(false);if(target instanceof Element&&!target.closest('.mobile-more-menu,.mobile-dock'))setMobileMoreOpen(false)};const escape=(event:KeyboardEvent)=>{if(event.key==='Escape'){setRoleMenuOpen(false);setFilterMenuOpen(false);setMobileMoreOpen(false);setDialog(null);setSelected(null);if(tourStep!==null){safeStorage.setItem('sajag.tour.completed','true');setTourStep(null)}}};document.addEventListener('pointerdown',dismiss);window.addEventListener('keydown',escape);return()=>{document.removeEventListener('pointerdown',dismiss);window.removeEventListener('keydown',escape)}},[tourStep]);
